### b. Global error‑handler middleware

```js
// middleware/errorHandler.js
module.exports = (err, _req, res, _next) => {
  // Log the error (you can replace this with Winston/Bunyan, etc.)
  console.error(err);

  const status = err.status || 500;
  const response = {
    error: {
      message: status === 500 ? 'Internal Server Error' : err.message,
      // Optionally expose a code for the client – never expose stack traces in prod
