```js
// app.js – security‑enhanced starter
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, query, param, validationResult } = require('express-validator');
const pino = require('pino');
const pinoHttp = require('pino-http');

const logger = pino({ level: process.env.LOG_LEVEL || 'info' });
const app = express();

// ---------------------
// 1️⃣  Global middleware
// ---------------------

// Trust proxy if behind a load‑balancer (required for rate‑limit & HTTPS redirect)
app.set('trust proxy', 1);

// Security headers
app.use(helmet());

// CORS – restrict origins in production
app.use(
  cors({
    origin: process.env.ALLOWED_ORIGINS?.split(',') || '*', // <‑ change to whitelist
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
  })
);

// Structured request logging
app.use(pinoHttp({ logger }));

// Rate limiting (example: 100 req / 15 min per IP)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsers – keep limits low
app.use(express.json({ limit: '1kb' }));
app.use(express.urlencoded({ extended: false, limit: '1kb' }));

// -------------------------------------------------
// 2️⃣  Helper: validation result formatter middleware
// -------------------------------------------------
function handleValidationErrors(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Do NOT expose raw validation messages – map to generic response
    return res.status(400).json({
      error: 'Invalid request parameters',
      details: errors.array().map((e) => e.msg), // optional, can be omitted in prod
    });
  }
  next();
}

// ---------------------
// 3️⃣  Routes
// ---------------------

app.get('/health', (req, res) => {
  // Minimal info – avoid revealing internal data
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get(
  '/users',
  // Example: allow optional pagination query params
  [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .toInt()
      .withMessage('page must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt()
      .withMessage('limit must be between 1 and 100'),
    handleValidationErrors,
  ],
  (req, res) => {
    // In a real app this would query a DB with pagination
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  }
);

// ---------------------
// 4️⃣  Central error handler
// ---------------------
app.use((err, req, res, next) => {
  // Log the full stack trace for operators
  req.log.error({ err }, 'Unhandled error in request pipeline');

  // Do not leak implementation details to the client
  const status = err.status || 500;
  const message = status === 500 ? 'Internal server error' : err.message;
  res.status(status).json({ error: message });
});

// ---------------------
// 5️⃣  Process‑level safety nets
// ---------------------
process.on('unhandledRejection', (reason) => {
  logger.error({ reason }, 'Unhandled Promise Rejection – shutting down');
  // Graceful shutdown logic here (close DB, server, etc.)
  process.exit(1);
});

process.on('uncaughtException', (err) => {
  logger.fatal({ err }, 'Uncaught Exception – shutting down');
  process.exit(1);
});

// ---------------------
// 6️⃣  Server start
// ---------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

module.exports = app;
```

**Key take‑aways from the example**

1. **Helmet** adds a solid baseline of HTTP‑header protections.
2. **Rate limiting** thwarts basic denial‑of‑service and credential‑guessing attacks.
3. **CORS** is explicitly configured; replace `'*'` with a concrete whitelist for production.
4. **Structured logging** (Pino) gives you searchable logs without exposing them to the client.
5. **Input validation** (express‑validator) is demonstrated for optional pagination parameters; the same pattern can be reused for body payloads, path params, etc.
6. **Central error middleware** guarantees a consistent JSON error shape and prevents accidental stack‑trace leakage.
7. **Process‑level handlers** ensure the app doesn’t stay in an inconsistent state after a fatal error.

You can adopt these practices incrementally—start by adding Helmet and a simple error‑handler, then bring in validation and rate limiting as your API surface expands. This will dramatically improve the security posture of the application without altering its current behaviour.

