// app.js – production‑ready starter
/* eslint-disable no-console */ // (remove when you adopt a proper logger)

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { celebrate, Joi, errors, Segments } = require('celebrate'); // validation lib
require('express-async-errors'); // patches Express to forward async errors

// -------------------------------------------------------------------
// Configuration
// -------------------------------------------------------------------
const PORT = process.env.PORT || 3000;
const ALLOWED_ORIGINS = (process.env.CORS_ORIGINS || '').split(',').filter(Boolean);
// If you don't need CORS, you can set ALLOWED_ORIGINS to [].

const app = express();

// -------------------------------------------------------------------
// Global Middleware
// -------------------------------------------------------------------
app.use(helmet()); // security headers
app.use(express.json()); // body parser for JSON payloads

// Simple request logger – replace with pino/winston for production
app.use(morgan('combined'));

// CORS – restrict to whitelisted origins; set to '*' for open APIs
app.use(
  cors({
    origin: (origin, callback) => {
      // Allow REST clients (no origin) and whitelisted domains
      if (!origin || ALLOWED_ORIGINS.includes(origin)) {
        return callback(null, true);
      }
      return callback(new Error('Not allowed by CORS'));
    },
  })
);

// Rate limiting – 100 requests per 15‑minute window per IP (adjust to suit)
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use('/users', apiLimiter); // apply only where needed (example)

// -------------------------------------------------------------------
// Helper: async wrapper (optional – you already have express-async-errors)
// -------------------------------------------------------------------
// const asyncHandler = fn => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);

// -------------------------------------------------------------------
// Routes
// -------------------------------------------------------------------

// Health check – no validation needed
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example: Users list – still static, but we show validation for future query params
app.get(
  '/users',
  // Validation block – any query parameters can be declared here
  celebrate({
    [Segments.QUERY]: Joi.object({
      // Example: ?limit=10
      limit: Joi.number().integer().min(1).max(100).default(10),
    }),
  }),
  (req, res) => {
    const limit = req.query.limit; // now guaranteed to be a number within range
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(allUsers.slice(0, limit));
  }
);

// -------------------------------------------------------------------
// Celebrate error formatter (validation errors)
// -------------------------------------------------------------------
app.use(errors());

// -------------------------------------------------------------------
// Centralised error handling
// -------------------------------------------------------------------
app.use((err, req, res, next) => {
  // Log the error – replace with a proper logger in prod
  console.error(`[${new Date().toISOString()}]`, err);

  // Do NOT expose stack traces to the client in production
  const status = err.status || err.statusCode || 500;
  const response = {
    error: err.message || 'Internal Server Error',
  };

  // Optionally add a generic errorId for correlation (e.g., UUID)
  // response.errorId = req.id; // if you use a request‑id middleware

  res.status(status).json(response);
});

// -------------------------------------------------------------------
// Server bootstrap – graceful shutdown support
// -------------------------------------------------------------------
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
function shutdown(signal) {
  console.log(`Received ${signal}. Shutting down gracefully...`);
  server.close(() => {
    console.log('Closed remaining connections. Exiting now.');
    process.exit(0);
  });
  // Force exit after 10s if connections hang
  setTimeout(() => process.exit(1), 10_000).unref();
}
process.on('SIGINT', () => shutdown('SIGINT'));
process.on('SIGTERM', () => shutdown('SIGTERM'));

module.exports = app;
```

### What changed?

