```js
// app.js – secure, production‑ready Express starter
require('dotenv').config();               // Load .env (dev only)
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, param, query, validationResult } = require('express-validator');

const app = express();

// -------------------------------------------------
// 1️⃣  Core security & middleware
// -------------------------------------------------
app.use(helmet());                         // Secure HTTP headers
app.use(
  cors({
    origin: process.env.CORS_ORIGIN?.split(',') || '*', // whitelist or allow all in dev
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
    credentials: true,
  })
);

// Limit request bodies to 100 KB (adjust as needed)
app.use(express.json({ limit: '100kb' }));

// Basic request logging – replace with winston/pino for production
app.use(morgan('combined'));

// Rate limiting – 100 req/min per IP (tune for your use‑case)
const limiter = rateLimit({
  windowMs: 60_000,
  max: 100,
  standardHeaders: true,   // Return RateLimit-* headers
  legacyHeaders: false,
});
app.use(limiter);

// -------------------------------------------------
// 2️⃣  Routes
// -------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * In a real API you would pull users from a DB.
 * Here we keep it static but we still illustrate how to
 * validate possible query parameters (e.g., pagination).
 */
app.get(
  '/users',
  // Example validation – optional `page` query param, must be integer >= 1
  query('page')
    .optional()
    .isInt({ min: 1 })
    .toInt()
    .withMessage('page must be a positive integer'),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // Forward to the error handler with status 400
      return next({ status: 400, message: errors.array() });
    }

    // If you later add pagination, use req.query.page here.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  }
);

// -------------------------------------------------
// 3️⃣  404 handler (must be after ALL routes)
// -------------------------------------------------
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not Found' });
});

// -------------------------------------------------
// 4️⃣  Central error handler
// -------------------------------------------------
app.use((err, req, res, next) => {
  // Log the full error for debugging (use a proper logger in prod)
  console.error(err);

  const status = err.status || 500;
  const response = {
    error:
      status === 500
        ? 'Internal Server Error'
        : err.message || 'Unexpected error',
  };

  // In development you may want to expose stack traces:
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    response.stack = err.stack;
  }

  res.status(status).json(response);
});

// -------------------------------------------------
// 5️⃣  Server start – use env var, fallback to 3000
// -------------------------------------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.info(`🚀 Server running on http://localhost:${PORT}`);
});

// Graceful shutdown (useful for Docker/K8s)
function shutdown() {
  console.info('🔌 Shutting down gracefully...');
  server.close(() => {
    console.info('✅ Server closed');
    process.exit(0);
  });
  // Force exit after 10 seconds
  setTimeout(() => process.exit(1), 10_000);
}
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);

module.exports = app;
```

