const asyncHandler = require('./utils/asyncHandler');

// Example of a future async route
app.get(
  '/users',
  asyncHandler(async (req, res) => {
    // Placeholder for async DB call
    const users = await getUsersFromDB(); // <-- will be caught
    res.json(users);
  })
);

// Global error handler – must be the last middleware
app.use((err, req, res, next) => {
  // Log the error (replace console with a proper logger in prod)
  console.error(err);

  const status = err.status || 500;
  const response = {
    error: {
      message: status === 500 ? 'Internal Server Error' : err.message,
      // Optionally expose validation details in dev only
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
    }
  };
  res.status(status).json(response);
});
```

