require('dotenv').config();               // Load .env (if you use it)
require('express-async-errors');          // Auto‑capture async errors

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');

const app = express();

// ----- 1. Basic security middlewares ------------------------------------
app.disable('x-powered-by');
app.set('trust proxy', 1); // adjust if you are behind a proxy

app.use(helmet({
  // You can override defaults here, e.g.:
  // contentSecurityPolicy: false, // if you don't serve HTML yet
}));

app.use(cors({
  origin: ['https://myapp.example.com'], // <-- replace with your allowed origins
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true,
}));

app.use(morgan('combined')); // logs to STDOUT; swap for winston in prod

// ----- 2. Rate limiting ------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // limit each IP
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ----- 3. Body parsers (if you will accept JSON later) -----------------
app.use(express.json());
app.use(express.urlencoded({ extended: false }));

// ----- 4. Routes --------------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real app this would come from a DB – no user‑supplied data now
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ----- 5. 404 handler ---------------------------------------------------
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not Found' });
});

// ----- 6. Central error handler -----------------------------------------
app.use((err, req, res, next) => {
  // Log the stack trace for debugging (replace with winston in prod)
  console.error(err);

  const status = err.status || 500;
  const message =
    process.env.NODE_ENV === 'production'
      ? 'Internal Server Error'
      : err.message;

  res.status(status).json({ error: message });
});

// ----- 7. Server start --------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

