  // Log the error (use a proper logger in real code)
  console.error(err);

  // Do not expose internal details in production
  const response = {
    status: 'error',
    message: process.env.NODE_ENV === 'production'
      ? 'Internal Server Error'
      : err.message,
    // Optional: add a code or validation details here
