## 4. Refactor Existing Routes with the New Patterns

Below is a **drop‑in replacement** for the original file that incorporates the above suggestions while keeping the original functionality.

```js
// app.js – hardened version
require('dotenv').config(); // load .env (ignore in production if using other secret mgmt)

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { celebrate, Joi, errors, Segments } = require('celebrate');

const app = express();

// ---------- Security Hardening ----------
app.use(helmet());

const apiLimiter = rateLimit({
  windowMs: 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(apiLimiter);

app.use(express.json({ limit: '100kb' }));

app.use(
  cors({
    origin: process.env.CORS_ORIGIN?.split(',') || [],
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
  })
);

if (process.env.NODE_ENV !== 'production') {
  app.use(morgan('dev'));
} else {
  app.use(morgan('combined'));
}

// ---------- Helper ----------
const asyncHandler = fn => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

// ---------- Routes ----------
app.get(
  '/health',
  asyncHandler(async (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  })
);

app.get(
  '/users',
  asyncHandler(async (req, res) => {
    // In a real app, replace the hard‑coded array with DB call
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  })
);

// Placeholder for a future POST endpoint demonstrating validation
app.post(
  '/users',
  celebrate({
    [Segments.BODY]: Joi.object({
      name: Joi.string().trim().min(2).max(100).required(),
      email: Joi.string().email().required(),
    }),
  }),
  asyncHandler(async (req, res) => {
    const { name, email } = req.body;
    // Insert user into DB here…
    res.status(201).json({ id: 3, name, email });
  })
);

// Celebrate validation error formatter
app.use(errors());

// ---------- Central Error Handler ----------
app.use((err, req, res, next) => {
  console.error(err); // swap with a real logger in prod
  const isProd = process.env.NODE_ENV === 'production';
  const status = err.status || 500;
  const message =
    isProd && status === 500
      ? 'Internal Server Error'
      : err.message || 'Unexpected error';

  res.status(status).json({
    error: {
      message,
      ...(isProd ? {} : { stack: err.stack }),
    },
  });
});

// ---------- Server bootstrap ----------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown (helps with container/k8s restarts)
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

function shutdown() {
  console.log('Shutting down gracefully...');
  server.close(() => {
    console.log('Closed out remaining connections.');
    process.exit(0);
  });

  // Force‑close after 10 seconds
  setTimeout(() => {
    console.error('Forcefully shutting down.');
    process.exit(1);
  }, 10_000);
}

module.exports = app;
```

### What changed?

| Area | Original | Hardened version |
|------|----------|------------------|
| **Port** | Fixed `3000` | `process.env.PORT || 3000` |
| **Headers** | None | `helmet()` |
| **Rate limiting** | None | `express-rate-limit` |
| **CORS** | None | `cors` with whitelist |
| **Logging** | `console.log` only | `morgan` (dev vs combined) |
| **JSON body size** | Not parsed | `express.json({ limit: '100kb' })` |
| **Async error handling** | Synchronous, no `try/catch` | `asyncHandler` helper |
| **Error responses** | None (unhandled errors crash) | Centralised error middleware, hides stack traces in prod |
| **Input validation** | No user input | Example `POST /users` with `celebrate` + `Joi` |
| **Graceful shutdown** | None | `SIGTERM/SIGINT` listeners |
| **Environment configuration** | None | `.env` loading, `CORS_ORIGIN`, `NODE_ENV`, etc. |

